/** Modules generated by content-plugin.ts at build time. */
declare module "virtual:chronexa-docs" {
  export type DocHeading = { depth: number; id: string; text: string };
  export type DocPage = { slug: string; title: string; html: string; headings: DocHeading[] };
  export type SearchEntry = {
    slug: string;
    page: string;
    id: string;
    heading: string;
    text: string;
  };
  export const pages: DocPage[];
  export const search: SearchEntry[];
}

declare module "virtual:chronexa-snippets" {
  /** Highlighted HTML for each file in demo/snippets/, keyed by path without the extension. */
  const snippets: Record<string, string>;
  export default snippets;
}
